import { APP_VERSION } from './version.js';

export function setupPage(error: string): string {
  const safeError = escapeHtml(error);
  return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>راه‌اندازی Scraper 4</title><style>:root{color-scheme:dark}body{margin:0;background:#07111e;color:#e8eef8;font:15px Tahoma;line-height:2}main{max-width:780px;margin:40px auto;padding:25px}.card{background:#101e31;border:1px solid #29415f;border-radius:15px;padding:22px;margin-top:15px}h1{color:#38bdf8}pre{direction:ltr;text-align:left;background:#050b13;border-radius:8px;padding:10px;display:block;overflow:auto}.error{color:#fda4af;border-color:#be123c}b{color:#fcd34d}</style></head><body><main><h1>Scraper 4 روی Render اجرا شد</h1><div class="card error"><b>پایگاه داده هنوز متصل نیست</b><br>${safeError}</div><div class="card"><h2>راه‌اندازی در سه مرحله</h2><ol><li>در Render گزینه <b>New → PostgreSQL</b> را انتخاب و دیتابیس بسازید.</li><li>مقدار <b>Internal Database URL</b> را کپی کنید.</li><li>در Environment سرویس وارد کنید:</li></ol><pre>DATABASE_URL = Internal Database URL
ADMIN_TOKEN = a-long-random-secret
RUN_WORKER_IN_WEB = true</pre><p>پس از Save Changes، سرویس Restart و جداول خودکار ساخته می‌شوند.</p></div></main></body></html>`;
}

