function initMenu(){$('menuSections').innerHTML=menuDefs.map(([title,key,desc,content])=>'<section class="menu-section" data-menu="'+key+'"><button class="menu-title"><span>'+title+'</span><i>▼</i></button><div class="menu-content"><p class="menu-text">'+desc+'</p>'+content+'</div></section>').join('')}
function initFields(){ $('selectorGrid').innerHTML=listFields.map(([id,label])=>fieldHtml(id,label,id==='container'?'li.product':id==='title'?'h2':id==='price'?'.price':id==='link'?'a[href]':'img')).join(''); $('detailGrid').innerHTML=detailFields.map(([id,label])=>fieldHtml(id,label,'')).join('') }
function fieldHtml(id,label,value){return '<div class="sel-item" id="wrap-'+id+'"><div class="sel-title"><b>'+label+'</b><span>CSS</span></div><input id="sel-'+id+'" dir="ltr" value="'+escAttr(value)+'"><div id="result-'+id+'" class="sel-result">—</div></div>'}
const token=()=>($('token').value||'').trim(),headers=()=>({'content-type':'application/json',authorization:'Bearer '+token()});
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...headers(),...(options.headers||{})}}),text=await response.text();let data;try{data=JSON.parse(text)}catch{data={error:text||'HTTP '+response.status}}if(!response.ok)throw Error((data.detail||data.error||'HTTP '+response.status)+(data.selectorErrors?' · '+JSON.stringify(data.selectorErrors):''));return data}
function notice(message,kind='ok'){const el=$('notice');el.className='notice show '+kind;el.textContent=message;clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.classList.remove('show'),6000)}
function output(value){$('out').textContent=typeof value==='string'?value:JSON.stringify(value,null,2)}
function busy(button,on){button.disabled=on;if(on){button.dataset.old=button.textContent;button.textContent='در حال انجام…'}else if(button.dataset.old)button.textContent=button.dataset.old}
function drawer(open){$('drawer').classList.toggle('open',open);$('drawerOverlay').classList.toggle('open',open);if(open&&state.selected)for(const id of ['retireProfile','reconProfile','bulkProfile','photoProfile'])if($(id)&&!$(id).value)$(id).value=state.selected}
function nestedGet(obj,path){return path.split('.').reduce((value,key)=>value?.[key],obj)}
function nestedSet(obj,path,value){const keys=path.split('.');let node=obj;keys.slice(0,-1).forEach(key=>node=node[key]||(node[key]={}));node[keys.at(-1)]=value}
function applySettings(){document.querySelectorAll('[data-setting]').forEach(input=>{const value=nestedGet(state.settings,input.dataset.setting);if(value===undefined||value===null)return;if(input.type==='checkbox')input.checked=Boolean(value);else if(typeof value==='object')input.value=JSON.stringify(value,null,2);else input.value=String(value)})}
function applyConnections(){document.querySelectorAll('[data-connection]').forEach(input=>{const value=nestedGet(state.connections,input.dataset.connection);if(value===undefined||value===null)return;if(input.type==='checkbox')input.checked=Boolean(value);else if(typeof value==='object')input.value=JSON.stringify(value,null,2);else input.value=String(value)})}
function aiProvidersUi(){return Array.isArray(state.connections?.ai?.providers)?state.connections.ai.providers:[]}
function renderAi(){const providers=aiProvidersUi(),selectedId=state.connections?.ai?.activeProvider||providers[0]?.id||'',selected=providers.find(p=>p.id===selectedId)||providers[0];$('aiProviderPaste').value=JSON.stringify(providers,null,2);$('aiProviderSelect').innerHTML=providers.map(p=>'<option value="'+escAttr(p.id)+'">'+esc(p.name||p.id)+'</option>').join('')||'<option value="">—</option>';$('aiProviderSelect').value=selected?.id||'';$('aiModelSelect').innerHTML=(selected?.models||[]).map(m=>'<option>'+esc(m)+'</option>').join('');$('aiModelSelect').value=state.connections?.ai?.model||selected?.models?.[0]||'';$('aiProviderToggles').innerHTML=providers.map((p,i)=>'<label class="checks"><input type="checkbox" data-ai-toggle="'+i+'" '+(p.enabled!==false?'checked':'')+'> '+esc(p.name||p.id)+' · '+fa((p.models||[]).length)+' مدل</label>').join('');$('aiModelsList').innerHTML=providers.map(p=>'<div style="margin-bottom:8px"><b>'+esc(p.name||p.id)+' · '+fa((p.models||[]).length)+' مدل</b>'+(p.models||[]).map(m=>'<div class="row" style="justify-content:space-between;margin:3px 0"><code dir="ltr">'+esc(m)+'</code><button class="btn btn-gray btn-sm" data-ai-test-one="'+escAttr(p.id)+'::'+escAttr(m)+'">تست</button></div>').join('')+'</div>').join('')||'ارائه‌دهنده‌ای ثبت نشده.';const candidates=state.connections?.ai?.candidates||[];$('aiCandidateList').textContent=candidates.join('\n')||'کاندیدی نیست';$('aiCandidateProvider').innerHTML=providers.map(p=>'<option value="'+escAttr(p.id)+'">'+esc(p.name||p.id)+'</option>').join('');updateCandidateModels();$('aiMasterSelect').innerHTML='<option value="">خودکار</option>'+candidates.map(k=>'<option>'+esc(k)+'</option>').join('');$('aiMasterSelect').value=state.connections?.ai?.master||''}
function normalizeProviderImport(raw){const source=Array.isArray(raw)?raw:Object.entries(raw||{}).map(([id,p])=>({id,...p}));return source.map((p,i)=>({id:String(p.id||p.key||'provider-'+(i+1)),name:String(p.name||p.id||'Provider '+(i+1)),baseUrl:String(p.baseUrl||p.base_url||p.url||''),apiKey:String(p.apiKey||p.api_key||p.key||''),kind:p.kind||'openai',models:(Array.isArray(p.models)?p.models:[]).map(m=>typeof m==='string'?m:String(m.id||m.name||'')).filter(Boolean),enabled:p.enabled!==false}))}
function renderCandidateResults(data){const results=data.results||[],keys=results.map(x=>x.key);$('aiCandidateResult').innerHTML=results.map(row=>'<div class="item"><div class="row"><b dir="ltr">'+esc(row.key)+'</b><span class="ai-pill '+(row.ok?'ok':'fail')+'">'+(row.ok?'موفق':'خطا')+'</span></div><div class="ai-response">'+esc(row.text||row.error||'')+'</div>'+(row.ok?'<button class="btn btn-green btn-sm" data-candidate-vote="'+escAttr(row.key)+'" data-vote-keys="'+escAttr(JSON.stringify(keys))+'">✓ این پاسخ بهتر بود</button>':'')+'</div>').join('')||'نتیجه‌ای نیست'}
function updateCandidateModels(){$('aiCandidateModel').innerHTML=(aiProvidersUi().find(p=>p.id===$('aiCandidateProvider').value)?.models||[]).map(m=>'<option>'+esc(m)+'</option>').join('')}
function expectedAiRows(testState){const limit=Number(testState.options?.perProvider)||500,resultList=testState.results||[],results=new Map(resultList.map(x=>[x.key||x.provider+'::'+x.model,x])),base=aiProvidersUi().filter(p=>p.enabled!==false).flatMap(p=>(p.models||[]).slice(0,limit).map(model=>{const key=p.id+'::'+model;return results.get(key)||{key,provider:p.id,providerName:p.name,model,pending:true}}));if(testState.options?.onlyUntested&&testState.total<base.length){const pending=Math.max(0,Number(testState.total||0)-resultList.length);return[...resultList,...Array.from({length:pending},(_,i)=>({key:'pending-'+i,provider:'—',providerName:'—',model:'در انتظار',pending:true}))]}return base}
function openAiResults(testState){if(testState)state.aiTestState=testState;$('aiResultsModal').classList.add('open');renderAiResults()}
function closeAiResults(){$('aiResultsModal').classList.remove('open')}
function renderAiResults(){const st=state.aiTestState||{},all=expectedAiRows(st);state.aiResultRows=all;const done=all.filter(x=>!x.pending),ok=done.filter(x=>x.ok),fail=done.filter(x=>!x.ok),latencies=ok.map(x=>Number(x.latencyMs)||0).filter(Boolean),avg=latencies.length?Math.round(latencies.reduce((a,b)=>a+b,0)/latencies.length):0;$('aiStatTotal').textContent=fa(st.total||all.length);$('aiStatOk').textContent=fa(ok.length);$('aiStatFail').textContent=fa(fail.length);$('aiStatWait').textContent=fa(Math.max(0,(st.total||all.length)-done.length));$('aiStatLatency').textContent=avg?fa(avg)+'ms':'—';$('aiStatSuccess').textContent=done.length?fa(Math.round(ok.length/done.length*100))+'٪':'۰٪';$('aiResultCurrent').textContent=st.running?'در حال تست: '+(st.last||'…'):st.done?'پایان':'آماده';const selectedProvider=$('aiResultProvider').value;$('aiResultProvider').innerHTML='<option value="">همه ارائه‌دهنده‌ها</option>'+[...new Set(all.map(x=>x.provider))].map(p=>'<option>'+esc(p)+'</option>').join('');if([...$('aiResultProvider').options].some(x=>x.value===selectedProvider))$('aiResultProvider').value=selectedProvider;applyAiResultFilters();const groups={};for(const row of done){groups[row.provider]??={total:0,ok:0,latency:[]};groups[row.provider].total++;if(row.ok){groups[row.provider].ok++;if(row.latencyMs)groups[row.provider].latency.push(row.latencyMs)}}$('aiProviderSummary').textContent=Object.entries(groups).map(([p,g])=>p+': '+g.ok+'/'+g.total+' موفق · میانگین '+(g.latency.length?Math.round(g.latency.reduce((a,b)=>a+b,0)/g.latency.length):0)+'ms').join('  |  ')||'هنوز نتیجه‌ای ثبت نشده.'}
function applyAiResultFilters(){const query=normUi($('aiResultSearch').value),provider=$('aiResultProvider').value,status=$('aiResultStatus').value,sort=$('aiResultSort').value;let rows=[...state.aiResultRows].filter(row=>(!provider||row.provider===provider)&&(status==='all'||status==='ok'&&row.ok||status==='fail'&&!row.pending&&!row.ok||status==='pending'&&row.pending)&&(!query||normUi([row.providerName,row.provider,row.model,row.msgResponse,row.catResponse,row.error].join(' ')).includes(query)));if(sort==='latency-asc')rows.sort((a,b)=>(a.latencyMs||1e12)-(b.latencyMs||1e12));if(sort==='latency-desc')rows.sort((a,b)=>(b.latencyMs||0)-(a.latencyMs||0));if(sort==='provider')rows.sort((a,b)=>String(a.provider).localeCompare(String(b.provider)));if(sort==='model')rows.sort((a,b)=>String(a.model).localeCompare(String(b.model)));$('aiResultBody').innerHTML=rows.map((row,index)=>'<tr><td>'+fa(index+1)+'</td><td><span class="ai-pill '+(row.pending?'':row.ok?'ok':'fail')+'">'+(row.pending?'⏳ انتظار':row.ok?'🟢 موفق':'🔴 ناموفق')+'</span></td><td>'+esc(row.providerName||row.provider||'')+'</td><td dir="ltr">'+esc(row.model||'')+'</td><td>'+(row.latencyMs?fa(row.latencyMs)+'ms':'—')+'</td><td><div class="ai-response">'+esc(row.msgResponse||row.text||'')+'</div></td><td><div class="ai-response">'+esc(row.catResponse||row.category||'')+'</div></td><td><div class="ai-response off">'+esc(row.error||'')+'</div></td></tr>').join('')||'<tr><td colspan="8" class="empty">نتیجه‌ای مطابق فیلتر نیست.</td></tr>'}
function exportAiResults(){const fields=['provider','model','ok','latencyMs','msgResponse','catResponse','error'],lines=[fields.join(','),...state.aiResultRows.filter(x=>!x.pending).map(row=>fields.map(key=>'"'+String(row[key]??'').replace(/"/g,'""')+'"').join(','))],blob=new Blob(['\uFEFF'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ai-model-results-'+Date.now()+'.csv';a.click();URL.revokeObjectURL(a.href)}
function normUi(value){return String(value||'').toLowerCase().replace(/\s+/g,' ').trim()}
async function refreshAiResults(){const d=await api('/api/ai/test-status');state.aiTestState=d.state;openAiResults(d.state);$('aiTestResult').textContent=JSON.stringify(d.state,null,2)}
